const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=localStorage;}catch{}
let preferences={scale:1,zoom:21,sound:false,view:'iso'};try{const old=JSON.parse(storage?.getItem('mosslight-raid-settings'));if(old){preferences.scale=[1,.85,.7].includes(old.scale)?old.scale:1;preferences.zoom=Number.isFinite(old.zoom)?Math.max(17,Math.min(29,old.zoom)):21;preferences.sound=old.sound===true;preferences.view=old.view==='first'?'first':'iso';}}catch{}
const audio=new IslandAudio(),world=new RaidWorld($('raidCanvas'));world.scale=preferences.scale;world.zoom=preferences.zoom;world.setView(preferences.view);world.resize();
let profile=loadProfile(storage),paused=false,menuOpen=false,toastTimer,lastSave=0,lastHud=0,last=performance.now(),accumulator=0,frameNo=0,lastCampDraw=0,aim={x:SPAWN.x,z:SPAWN.z-8};
let chosenWeapon='pistol',chosenContract='supplies',activePanel='',mouse={x:innerWidth/2,y:innerHeight/2,down:false,seen:false},touchMove={x:0,y:0},touchAim={x:0,y:0,active:false};
const keys=new Set(),ray=new THREE.Raycaster(),ndc=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),aimHit=new THREE.Vector3();
const metrics={frames:[],frameCount:0,fixedSteps:0,activeSamples:[],longFrames:0},damageLabels=[];
function save(p=profile){try{storage?.setItem(RAID_KEY,JSON.stringify(p));}catch{if(!save.warned){save.warned=true;toast('浏览器未能保存。可在营地导出存档备份。');}}}
function savePreferences(){try{storage?.setItem('mosslight-raid-settings',JSON.stringify(preferences));}catch{}}
function toast(text){if(!text)return;$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3100);if(menuOpen){const feedback=$('panelFeedback');if(feedback)feedback.textContent=text;}}
function onEvent(event){
  if(event.type==='shot'){audio.tone(event.weapon==='shotgun'?95:190,.055,.1);return;}
  if(event.type==='hit'){showDamage(event.x,event.z,event.damage);audio.tone(320,.055,.07);return;}
  if(['roll','reload','equip','extract','pulse'].includes(event.type)){if(event.type==='pulse')audio.tone(220,.3,.15);return;}if(event.type==='swing'){audio.tone(130,.09,.08);return;}
  if(['loot','search','build','heal'].includes(event.type))audio.tone(540,.2,.15);
  if(event.type==='kill'){audio.tone(392,.28,.16);return;}
  if(event.type==='hurt'){$('hurtFlash').classList.remove('flash');requestAnimationFrame(()=>$('hurtFlash').classList.add('flash'));audio.tone(95,.15,.18);}
  if(event.type==='settled'){paused=false;menuOpen=false;clearInput();showSummary(event.summary);return;}
  if(event.type==='start'){showRaid();return;}
  toast(event.text);
}
let game=new RaidGame(profile,{event:onEvent,save});world.setLevel(game.level||makeLevel(4319));

for(let i=0;i<12;i++){const span=document.createElement('span');span.className='damage-number';span.hidden=true;$('effectsLayer').append(span);damageLabels.push({span,time:0,x:0,z:0});}
function showDamage(x,z,damage){const label=damageLabels.find(l=>l.time<=0)||damageLabels[0];label.x=x;label.z=z;label.time=.65;label.span.textContent=Math.round(damage);label.span.hidden=false;}
function releaseMouse(){if(document.pointerLockElement=== $('raidCanvas'))document.exitPointerLock();}
function syncView(){const first=world.cameraMode==='first';document.body.classList.toggle('first-person',first);$('viewButton').textContent=first?'V · 第一人称':'V · 第三人称';$('viewButton').setAttribute('aria-pressed',String(first));$('aimStick').querySelector('span').textContent=first?'转向 / 开火':'瞄准 / 开火';}
function switchView(){if(!game.run||paused)return;const next=world.cameraMode==='first'?'iso':'first';if(next==='first'){const p=game.run.player;world.viewYaw=Math.atan2(p.x-aim.x,p.z-aim.z);}world.setView(next);preferences.view=next;savePreferences();clearInput();if(next==='iso')releaseMouse();syncView();toast(next==='first'?'第一人称：点击画面捕获鼠标，转动瞄准；Esc 释放并暂停。':'第三人称跟随：鼠标指向目标，滚轮调整远近。');}
function clearInput(){keys.clear();mouse.down=false;touchMove.x=0;touchMove.y=0;touchAim.active=false;}
function setGameInert(value){$('raidHud').inert=value;$('raidCanvas').inert=value;}
function showRaid(){
  document.body.classList.add('inRaid');$('camp').hidden=true;$('summary').hidden=true;$('panelBackdrop').hidden=true;$('raidHud').hidden=false;activePanel='';menuOpen=false;paused=false;setGameInert(false);clearInput();world.setLevel(game.level);syncView();$('raidCanvas').focus();
  if(preferences.sound&&!audio.enabled)audio.setEnabled(true);drawMapBase();updateHud();toast('搜索补给，保持弹药，再把战利品带出。E 搜索 / 左键射击 / 空格翻滚。');
}
function showCamp(){releaseMouse();document.body.classList.remove('inRaid');
  paused=false;menuOpen=false;activePanel='';$('camp').hidden=false;$('summary').hidden=true;$('raidHud').hidden=true;$('panelBackdrop').hidden=true;setGameInert(false);clearInput();$('campResume').hidden=!game.run;$('deploy').hidden=!!game.run;
  $('credits').textContent=profile.credits;$('campStats').textContent=`成功撤离 ${profile.stats.extracts} 次　·　累计击败 ${profile.stats.kills}　·　最高带出价值 ${profile.stats.best}`;
  const select=$('loadout');select.innerHTML=Object.entries(GUNS).map(([id,g])=>{const usable=profile.blueprints[id]||(profile.stash[id]||0)>0;return `<option value="${id}" ${usable?'':'disabled'}>${g.name}${profile.blueprints[id]?' · 保险携行':usable?' · 仓库一把':' · 需要图纸或战利品'}</option>`;}).join('');if(!profile.blueprints[chosenWeapon]&&!(profile.stash[chosenWeapon]>0))chosenWeapon='pistol';select.value=chosenWeapon;
  $('contract').value=chosenContract;$('campKit').textContent=`生命 ${game.maxHealth()} / 护甲 ${game.maxArmor()} / 负重 ${game.capacity()} / 起始弹药 90 / 医疗包 1`;
}
function showSummary(summary){releaseMouse();document.body.classList.remove('inRaid');
  $('raidHud').hidden=true;$('camp').hidden=true;$('panelBackdrop').hidden=true;$('summary').hidden=false;setGameInert(false);
  $('summaryTitle').textContent=summary.success?'战利品，带回来了。':'人回来了，下次再出发。';$('summaryEyebrow').textContent=summary.success?'EXTRACTION COMPLETE / 成功撤离':'RESCUED / 本局回收失败';
  $('summaryReason').textContent=summary.success?'本局战利品已入库，仓库与升级会永久保留。':'本局背包与非保险装备遗失，仓库和永久升级保留。';
  $('summaryNumbers').innerHTML=`<div><strong>${Math.floor(summary.time/60)}:${Math.floor(summary.time%60).toString().padStart(2,'0')}</strong><span>行动时间</span></div><div><strong>${summary.kills}</strong><span>击败守卫</span></div><div><strong>${summary.success?summary.value:0}</strong><span>带出价值</span></div><div><strong>+${summary.reward}</strong><span>信用点</span></div>`;
  $('summaryItems').innerHTML=Object.entries(summary.bag).filter(([,n])=>n>0).map(([id,n])=>`<span style="--item:${ITEMS[id].color}">${ITEMS[id].name} ×${n}</span>`).join('')||'<span>本次没有战利品。</span>';
  $('summaryContract').textContent=summary.contractComplete?'委托完成，奖励已到账。':summary.success?'本次未完成额外委托，可在下次出击继续挑战。':summary.reason;audio.success();
}
function openPanel(title,html,id=''){menuOpen=true;releaseMouse();paused=true;activePanel=id;clearInput();audio.pause(true);$('panelTitle').textContent=title;$('panelBody').innerHTML=html+'<p id="panelFeedback" class="panel-feedback" role="status"></p>';$('panelBackdrop').hidden=false;setGameInert(true);requestAnimationFrame(()=>$('panelBody').querySelector('button,input,select')?.focus());}
function closePanel(){menuOpen=false;paused=false;activePanel='';$('panelBackdrop').hidden=true;setGameInert(false);clearInput();audio.pause(false);$('raidCanvas').focus();if(!game.run)showCamp();}
function inventory(){if(!game.run)return;const r=game.run,p=r.player;
  openPanel('行动背包',`<p>重量 ${bagWeight(r.bag).toFixed(1)} / ${game.capacity()}，携带价值 ${bagValue(r.bag)}。成功撤离才会入库；打开背包时单机行动暂停。</p><div class="inventory-grid">${Object.entries(r.bag).filter(([,n])=>n>0).map(([id,n])=>`<article style="--item:${ITEMS[id].color}"><i></i><b>${ITEMS[id].name}</b><span>×${n} · 单价 ${ITEMS[id].value} · 重 ${ITEMS[id].weight}</span><button data-drop="${id}">丢弃一个</button>${GUNS[id]?`<button data-equip="${id}">装备</button>`:''}${id==='med'?'<button data-heal>使用医疗包</button>':''}</article>`).join('')||'<div class="empty">背包还空着，搜索补给箱或采集方块。</div>'}</div><div class="weapon-choices">${game.weapons().map(id=>`<button data-equip="${id}">${p.weapon===id?'✓ ':''}${GUNS[id].name} ${p.mags[id]??GUNS[id].clip}</button>`).join('')}</div><button class="primary" id="backToRun">继续行动 ↗</button>`,'bag');
  document.querySelectorAll('[data-drop]').forEach(b=>b.onclick=()=>{game.dropItem(b.dataset.drop);inventory();});document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{game.equip(b.dataset.equip);inventory();});document.querySelector('[data-heal]')?.addEventListener('click',()=>{game.heal();closePanel();});$('backToRun').onclick=closePanel;
}
function stash(){openPanel('米洛的仓库',`<p>仓库中的物品不会因出击失败丢失。零件与材料可留给岚锻造，也可以出售换取信用点。</p><div class="panel-wallet">信用点 <b>${profile.credits}</b></div><div class="inventory-grid">${Object.entries(profile.stash).filter(([id,n])=>ITEMS[id]&&n>0).map(([id,n])=>`<article style="--item:${ITEMS[id].color}"><i></i><b>${ITEMS[id].name}</b><span>×${n} · 出售价 ${ITEMS[id].value}</span><button data-sell="${id}">出售一个</button></article>`).join('')||'<div class="empty">成功撤离后，战利品会出现在这里。</div>'}</div>`,'stash');document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{game.sell(b.dataset.sell);stash();});}
function forge(){openPanel('岚的工坊',`<p>已解锁的图纸可在营地保险携行。临时搜到的武器也能直接使用，成功带出后存入仓库。</p><div class="panel-wallet">信用点 <b>${profile.credits}</b></div><div class="forge-grid">${['shotgun','rifle'].map(id=>`<article><span class="eyebrow">${id==='shotgun'?'近距爆发':'连续压制'}</span><h3>${GUNS[id].name}</h3><p>${id==='shotgun'?'废铁 6 · 武器零件 3 · 信用点 75':'废铁 10 · 电池 3 · 零件 5 · 信用点 135'}</p><button data-craft="${id}" ${profile.blueprints[id]?'disabled':''}>${profile.blueprints[id]?'图纸已解锁':'解锁保险图纸'}</button></article>`).join('')}</div><h3>永久整备</h3><div class="upgrade-grid">${[['health','生命强化'],['armor','护甲强化'],['bag','背包扩容']].map(([id,label])=>`<button data-upgrade="${id}">${label} Lv.${profile.upgrades[id]} / 5<small>${profile.upgrades[id]>=5?'已满级':'花费 '+(70+profile.upgrades[id]*55)+' 信用点'}</small></button>`).join('')}</div>`,'forge');
  document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{const ok=game.craft(b.dataset.craft);if(ok)forge();});document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.upgrade))forge();});}
function settings(){openPanel('清晰、顺手地行动',`<label class="setting">画面清晰度<select id="quality"><option value="1">高清 · 默认，不动态降画质</option><option value="0.85">均衡 · 85% 渲染尺寸</option><option value="0.7">流畅 · 70% 渲染尺寸</option></select></label><label class="setting">镜头范围<input id="zoom" type="range" min="17" max="29" value="${preferences.zoom}"></label><p>V 或行动画面的视角按钮，切换第三人称跟随与第一人称。第三人称可滚轮调整远近；第一人称点击画面捕获鼠标，左右转向瞄准，WASD 相对朝向移动，Esc 释放并暂停。触屏使用右摇杆转向并射击。两种视角共享水平弹道、背包与行动进度。</p><button id="audioToggle">环境与战斗音效：${audio.enabled?'开':'关'}</button><button id="exportProfile">导出仓库与进度备份</button><button id="importProfile">导入备份（需要确认）</button><input id="profileFile" type="file" accept=".json,application/json" hidden><p>WASD 移动，鼠标瞄准，左键开火，空格/右键翻滚，R 换弹，E 按住搜索/采集，Q 脉冲，F 放置掩体，H 治疗，T 切换生存镐，Tab 背包。</p>`,'settings');
  $('quality').value=String(preferences.scale);$('quality').onchange=e=>{preferences.scale=Number(e.target.value);world.scale=preferences.scale;world.resize();savePreferences();};$('zoom').oninput=e=>{preferences.zoom=Number(e.target.value);world.zoom=preferences.zoom;world.resize();savePreferences();};$('audioToggle').onclick=async()=>{await audio.setEnabled(!audio.enabled);preferences.sound=audio.enabled;savePreferences();$('audioToggle').textContent='环境与战斗音效：'+(audio.enabled?'开':'关');};$('exportProfile').onclick=exportProfile;$('importProfile').onclick=()=>$('profileFile').click();$('profileFile').onchange=importProfile;
}
function exportProfile(){game.persist();const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(profile,null,2)],{type:'application/json'}));a.href=url;a.download='苔光边境回收_仓库备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function importProfile(e){const file=e.target.files?.[0];if(!file)return;try{if(file.size>150000)throw Error();const raw=JSON.parse(await file.text());if(raw.version!==3||!raw.stash||!raw.upgrades)throw Error();const next=parseProfile(raw);openPanel('恢复这份仓库？',`<p>备份有 ${next.credits} 信用点、${next.stats.extracts} 次成功撤离记录。确认后将替换当前仓库与行动状态。</p><button class="primary" id="confirmImport">确认恢复</button><button id="cancelImport">保留当前进度</button>`,'confirm');$('cancelImport').onclick=settings;$('confirmImport').onclick=()=>{profile=next;game=new RaidGame(profile,{event:onEvent,save});save();menuOpen=false;paused=false;setGameInert(false);$('panelBackdrop').hidden=true;if(game.run)world.setLevel(game.level);showCamp();};}catch{toast('无法读取备份，请选择本游戏导出的仓库 JSON。');}}
function pauseMenu(){if(menuOpen){closePanel();return;}if(!game.run||!$('camp').hidden){settings();return;}openPanel('暂时整备',`<p>单机行动已暂停，回收窗口与敌人也会等你。</p><button class="primary" id="resumeRaid">继续行动</button><button id="saveToCamp">保存本局并返回营地</button><button id="openSettings">画面与操作设置</button><button id="abandonRaid" class="danger">放弃本局（损失携带物）</button>`,'pause');$('resumeRaid').onclick=closePanel;$('saveToCamp').onclick=()=>{game.persist();audio.pause(false);showCamp();};$('openSettings').onclick=settings;$('abandonRaid').onclick=()=>{openPanel('确认放弃本局？','<p>本局背包和非保险武器会遗失，仓库与永久升级保留。</p><button class="danger" id="confirmAbandon">确认放弃</button><button id="cancelAbandon">返回行动</button>','confirm');$('confirmAbandon').onclick=()=>{closePanel();game.settle(false,'主动放弃本局行动');};$('cancelAbandon').onclick=closePanel;};}

$('deploy').onclick=()=>{chosenWeapon=$('loadout').value;chosenContract=$('contract').value;game.start(chosenWeapon,chosenContract);};$('campResume').onclick=showRaid;$('stashButton').onclick=stash;$('forgeButton').onclick=forge;$('settingsButton').onclick=settings;$('summaryBack').onclick=showCamp;$('panelClose').onclick=closePanel;$('bagButton').onclick=inventory;$('pauseButton').onclick=pauseMenu;$('medButton').onclick=()=>game.run&&game.heal();$('pulseButton').onclick=()=>game.run&&game.pulse();$('reloadButton').onclick=()=>game.run&&game.reload();$('buildButton').onclick=()=>game.run&&game.build(aim.x,aim.z);
$('viewButton').onclick=switchView;syncView();
window.addEventListener('resize',()=>world.resize());
function movement(){const sx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touchMove.x,sy=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-touchMove.y,yaw=world.cameraMode==='first'?world.viewYaw:Math.atan2(8,13);return{dx:Math.cos(yaw)*sx-Math.sin(yaw)*sy,dz:-Math.sin(yaw)*sx-Math.cos(yaw)*sy};}
function dodge(){if(!game.run||paused)return;const m=movement();game.roll(m.dx,m.dz);}
window.addEventListener('keydown',e=>{
  if(e.code==='Tab'&&menuOpen){const focusable=[...$('panelBackdrop').querySelectorAll('button:not([disabled]),input:not([hidden]),select')].filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
  if(e.code==='Escape'){e.preventDefault();if(!e.repeat)pauseMenu();return;}if(menuOpen||!$('summary').hidden||!$('camp').hidden)return;
  if(['Tab','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(!game.run)return;
  if(e.code==='Space')dodge();if(e.code==='KeyR')game.reload();if(e.code==='KeyQ')game.pulse();if(e.code==='KeyF')game.build(aim.x,aim.z);if(e.code==='KeyH')game.heal();if(e.code==='Tab'||e.code==='KeyB')inventory();if(e.code==='KeyT')game.run.player.tool=!game.run.player.tool;
  if(['Digit1','Digit2','Digit3'].includes(e.code)){game.run.player.tool=false;game.equip(['pistol','shotgun','rifle'][Number(e.code.slice(-1))-1]);}
  if(e.code==='KeyV')switchView();if(e.code==='KeyM')$('minimapCard').hidden=!$('minimapCard').hidden;
});window.addEventListener('keyup',e=>keys.delete(e.code));
$('raidCanvas').addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;if(world.cameraMode==='first'){if(!paused&&game.run&&(document.pointerLockElement===$('raidCanvas')||e.buttons===1))world.viewYaw-=e.movementX*.003;return;}mouse.x=e.clientX;mouse.y=e.clientY;mouse.seen=true;$('crosshair').style.transform=`translate(${e.clientX}px,${e.clientY}px)`;});
$('raidCanvas').addEventListener('pointerdown',e=>{if(!game.run||paused)return;if(e.button===2){e.preventDefault();dodge();}else if(e.button===0){if(world.cameraMode==='first'&&e.pointerType!=='touch'&&document.pointerLockElement!==$('raidCanvas')){try{const request=$('raidCanvas').requestPointerLock();request?.catch(()=>toast('鼠标捕获不可用，可按住左键拖动转向；V 返回第三人称。'));}catch{toast('按住左键拖动转向，V 返回第三人称。');}}mouse.x=e.clientX;mouse.y=e.clientY;mouse.seen=true;mouse.down=true;updateAim(0);if(game.run.player.tool)game.strike(aim.x,aim.z);else game.shoot(aim.x,aim.z);}});window.addEventListener('pointerup',()=>mouse.down=false);$('raidCanvas').addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&world.cameraMode==='first'&&game.run&&!menuOpen&&$('camp').hidden)pauseMenu();});
$('raidCanvas').addEventListener('wheel',e=>{e.preventDefault();if(world.cameraMode==='first')return;preferences.zoom=Math.max(17,Math.min(29,preferences.zoom+Math.sign(e.deltaY)));world.zoom=preferences.zoom;world.resize();savePreferences();},{passive:false});
function joystick(id,output,shoot=false){const base=$(id),knob=base.querySelector('i');let pointer=null;function change(e){const r=base.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,length=Math.hypot(dx,dy),radius=r.width*.35,factor=Math.min(1,radius/(length||1));output.x=dx*factor/radius;output.y=dy*factor/radius;if(shoot)output.active=true;knob.style.transform=`translate(${dx*factor}px,${dy*factor}px)`;}
  base.onpointerdown=e=>{if(paused||!game.run)return;e.preventDefault();pointer=e.pointerId;base.setPointerCapture(pointer);change(e);};base.onpointermove=e=>{if(e.pointerId===pointer)change(e);};for(const event of ['pointerup','pointercancel','lostpointercapture'])base.addEventListener(event,e=>{if(pointer===null||e.pointerId!==pointer)return;pointer=null;output.x=0;output.y=0;if(shoot)output.active=false;knob.style.transform='translate(0,0)';});}
joystick('moveStick',touchMove);joystick('aimStick',touchAim,true);$('touchRoll').onclick=dodge;$('touchInteract').onpointerdown=e=>{if(paused)return;e.preventDefault();keys.add('KeyE');$('touchInteract').setPointerCapture(e.pointerId);};for(const event of ['pointerup','pointercancel','lostpointercapture'])$('touchInteract').addEventListener(event,()=>keys.delete('KeyE'));
window.addEventListener('blur',()=>{clearInput();if(game.run&&!menuOpen&&$('camp').hidden)pauseMenu();});document.addEventListener('visibilitychange',()=>{if(document.hidden){game.persist();clearInput();if(game.run&&!menuOpen&&$('camp').hidden)pauseMenu();}});window.addEventListener('pagehide',()=>game.persist());

const map=$('minimap'),mc=map.getContext('2d'),mapBase=document.createElement('canvas');mapBase.width=GRID;mapBase.height=GRID;const mb=mapBase.getContext('2d');
function drawMapBase(){if(!game.level)return;for(let j=0;j<GRID;j++)for(let i=0;i<GRID;i++){const t=game.level.tiles[j*GRID+i];mb.fillStyle=t.kind==='floor'?'#8fa482':t.kind==='tree'?'#3f6555':t.kind==='cover'?'#c8af79':'#667f76';mb.fillRect(i,j,1,1);}}
function drawMap(){if(!game.run)return;const r=game.run;mc.clearRect(0,0,128,128);mc.imageSmoothingEnabled=false;mc.drawImage(mapBase,0,0,128,128);const xy=(x,z)=>[(x+HALF)/(HALF*2)*128,(z+HALF)/(HALF*2)*128];for(const e of EXITS){const [x,z]=xy(e.x,e.z);mc.fillStyle='#f1d49a';mc.fillRect(x-3,z-3,6,6);}CRATE_POS.forEach(([x,z],id)=>{if(r.crates.includes(id))return;const p=xy(x,z);mc.fillStyle='#cbdaba';mc.fillRect(p[0]-1,p[1]-1,3,3);});for(const e of r.enemies)if(e.hp>0){const p=xy(e.x,e.z);mc.fillStyle=e.type==='boss'?'#bda0d8':'#d99c8a';mc.fillRect(p[0]-1,p[1]-1,e.type==='boss'?4:2,e.type==='boss'?4:2);}const p=xy(r.player.x,r.player.z);mc.fillStyle='#fff7ce';mc.beginPath();mc.arc(p[0],p[1],2.8,0,Math.PI*2);mc.fill();}
function updateHud(){if(!game.run)return;const r=game.run,p=r.player,g=GUNS[p.weapon];$('hpText').textContent=Math.ceil(p.hp)+' / '+game.maxHealth();$('hpBar').style.width=(p.hp/game.maxHealth()*100)+'%';$('armorText').textContent=Math.ceil(p.armor);$('armorBar').style.width=(p.armor/game.maxArmor()*100)+'%';$('raidTime').textContent=Math.max(0,Math.floor((480-r.time)/60)).toString().padStart(2,'0')+':'+Math.max(0,Math.floor((480-r.time)%60)).toString().padStart(2,'0');$('bagValue').textContent=bagValue(r.bag);$('weight').textContent=bagWeight(r.bag).toFixed(1)+' / '+game.capacity();$('kills').textContent=r.kills;$('clockLabel').textContent=r.time>360?'边缘腐蚀 · 尽快撤离':'回收窗口';$('heat').textContent=Math.floor(r.heat);$('heat').classList.toggle('hot',r.heat>65);$('weaponName').textContent=p.tool?'生存镐':g.name;$('ammo').textContent=p.tool?'∞':p.mags[p.weapon];$('reserve').textContent=p.tool?'采集 / 近战':'/ '+p.reserve;$('reloadState').textContent=p.reload>0?'换弹中 '+p.reload.toFixed(1)+'s':p.heal>0?'治疗中 '+p.heal.toFixed(1)+'s':'R 换弹 · T 生存镐';$('medCount').textContent=p.meds+(r.bag.med||0);$('pulseCooldown').textContent=p.pulseCd>0?p.pulseCd.toFixed(1)+'s':'就绪';$('rollCooldown').textContent=p.rollCd>0?p.rollCd.toFixed(1)+'s':'就绪';
  $('contractName').textContent=CONTRACTS[r.contract]?.name||CONTRACTS.supplies.name;$('contractProgress').textContent=r.contract==='supplies'?(r.bag.battery||0)+'/2':r.contract==='hunter'?r.kills+'/5':(r.bag.core||0)+'/1';
  const target=game.nearby(aim.x,aim.z);$('interactHint').hidden=!target;$('interactText').textContent=target?.label||'';$('searchBar').style.width=target?.duration?Math.min(100,(game.searchProgress||0)/target.duration*100)+'%':'0%';
  const e=r.extraction;$('extraction').hidden=!e;if(e){$('extractText').textContent=e.blocked?'清理近处敌人，撤离暂停':Math.hypot(p.x-EXITS.find(x=>x.id===e.id).x,p.z-EXITS.find(x=>x.id===e.id).z)>2.25?'回到撤离光圈内':'撤离中 · '+Math.max(0,6-e.progress).toFixed(1)+'s';$('extractBar').style.width=e.progress/6*100+'%';}
  const boss=r.enemies.find(e=>e.type==='boss'&&e.hp>0&&Math.hypot(e.x-p.x,e.z-p.z)<15);$('bossHud').hidden=!boss;if(boss)$('bossHp').style.width=boss.hp/boss.maxHp*100+'%';$('zone').textContent=p.z>14?'南岸回收场':p.z<-6&&p.x>2?'北部遗迹 · 高风险区':p.x<-8?'苔木林地':'荒原中转区';drawMap();
}
function updateAim(dt){if(!game.run)return;const p=game.run.player;if(world.cameraMode==='first'){if(touchAim.active)world.viewYaw-=touchAim.x*dt*2.4;aim.x=p.x-Math.sin(world.viewYaw)*2.4;aim.z=p.z-Math.cos(world.viewYaw)*2.4;return;}if(touchAim.active){const length=Math.hypot(touchAim.x,touchAim.y);if(length>.15){const yaw=world.cameraMode==='first'?world.viewYaw:Math.atan2(8,13),sx=touchAim.x/length,sy=-touchAim.y/length;aim.x=p.x+(Math.cos(yaw)*sx-Math.sin(yaw)*sy)*12;aim.z=p.z+(-Math.sin(yaw)*sx-Math.cos(yaw)*sy)*12;}else{const nearest=game.run.enemies.filter(e=>e.hp>0&&Math.hypot(e.x-p.x,e.z-p.z)<13&&game.lineClear(p.x,p.z,e.x,e.z)).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0];if(nearest){aim.x=nearest.x;aim.z=nearest.z;}}return;}
  if(mouse.seen){ndc.set(mouse.x/innerWidth*2-1,-mouse.y/innerHeight*2+1);ray.setFromCamera(ndc,world.camera);if(ray.ray.intersectPlane(plane,aimHit)){aim.x=aimHit.x;aim.z=aimHit.z;}}else{aim.x=p.x;aim.z=p.z-8;}}
let lastMapRevision=-1;const phaseTimes=[];
function animate(now){const profileStart=performance.now();requestAnimationFrame(animate);const raw=Math.max(0,Math.min(.12,(now-last)/1000));last=now;metrics.frameCount++;if(game.run&&!paused&&$('camp').hidden){metrics.activeSamples.push(raw*1000);if(metrics.activeSamples.length>900)metrics.activeSamples.shift();if(raw>.05)metrics.longFrames++;updateAim(raw);accumulator=Math.min(.12,accumulator+raw);const move=movement();while(accumulator>=1/60){game.step(1/60,{...move,aimX:aim.x,aimZ:aim.z,fire:mouse.down||touchAim.active,interact:keys.has('KeyE'),sprint:keys.has('ShiftLeft')||keys.has('ShiftRight')});metrics.fixedSteps++;accumulator-=1/60;if(!game.run)break;}
    if(now-lastSave>5000){lastSave=now;game.persist();}if(now-lastHud>100){lastHud=now;if(game.level.revision!==lastMapRevision){lastMapRevision=game.level.revision;drawMapBase();}updateHud();}}
  else accumulator=0;
  const profileStepEnd=performance.now();world.visual(game,game.run?accumulator*60:1,raw,aim);
  for(const label of damageLabels)if(label.time>0){label.time-=raw;const p=world.project(label.x,label.z,1.3+(1-label.time/.65)*.6);label.span.style.transform=`translate(${p.x}px,${p.y}px)`;label.span.style.opacity=p.z<-1||p.z>1?'0':String(Math.min(1,label.time*4));if(label.time<=0)label.span.hidden=true;}
  const profileVisualEnd=performance.now();const active=game.run&&!paused&&$('camp').hidden;if(active||now-lastCampDraw>50){world.renderer.render(world.scene,world.camera);lastCampDraw=now;}
  if(active){phaseTimes.push([profileStepEnd-profileStart,profileVisualEnd-profileStepEnd,performance.now()-profileVisualEnd]);if(phaseTimes.length>600)phaseTimes.shift();}frameNo++;
}
showCamp();$('loading').hidden=true;window.gameReady=true;requestAnimationFrame(animate);
