window.raid={getState:()=>({phase:!$('summary').hidden?'summary':!$('camp').hidden?'camp':menuOpen?'paused':'raid',paused,profile:JSON.parse(JSON.stringify({...profile,run:null})),run:game.run?JSON.parse(JSON.stringify(game.run)):null,projectiles:game.bullets.length,diagnostics:world.metrics(),settings:{...preferences},timings:[0,1,2].map(i=>{const a=phaseTimes.map(t=>t[i]).sort((a,b)=>a-b);return{mean:a.reduce((s,n)=>s+n,0)/(a.length||1),p95:a[Math.floor(a.length*.95)]||0};}),nearby:game.run?game.nearby(aim.x,aim.z):null}),getMap:()=>game.level?{grid:GRID,tile:TILE,half:HALF,tiles:game.level.tiles.map(t=>t.kind),crates:CRATE_POS.map(([x,z],id)=>({id,x,z})),exits:EXITS.map(e=>({...e}))}:null,project:(x,z,y=0)=>world.project(x,z,y)};

